-- Cloudflare D1 / SQLite starter schema. Money is stored in integer paise.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS regions (id TEXT PRIMARY KEY, state TEXT NOT NULL, district TEXT NOT NULL, city TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, lat REAL NOT NULL, lng REAL NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS movies (id TEXT PRIMARY KEY, title TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, synopsis TEXT NOT NULL, runtime_minutes INTEGER, certification TEXT, languages_json TEXT NOT NULL, genres_json TEXT NOT NULL, poster_url TEXT, status TEXT NOT NULL, source TEXT NOT NULL, data_quality TEXT NOT NULL, last_updated_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS theatres (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, address TEXT NOT NULL, region_id TEXT NOT NULL REFERENCES regions(id), lat REAL NOT NULL, lng REAL NOT NULL, rating REAL, facilities_json TEXT NOT NULL, formats_json TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, source TEXT NOT NULL, data_quality TEXT NOT NULL, last_updated_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shows (id TEXT PRIMARY KEY, movie_id TEXT NOT NULL REFERENCES movies(id), theatre_id TEXT NOT NULL REFERENCES theatres(id), starts_at TEXT NOT NULL, ends_at TEXT, language TEXT NOT NULL, format TEXT NOT NULL, status TEXT NOT NULL, source TEXT NOT NULL, data_quality TEXT NOT NULL, last_updated_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS show_prices (id TEXT PRIMARY KEY, show_id TEXT NOT NULL REFERENCES shows(id), category TEXT NOT NULL, price_paise INTEGER NOT NULL, convenience_fee_paise INTEGER, tax_paise INTEGER, total_paise INTEGER, source TEXT NOT NULL, data_quality TEXT NOT NULL, fetched_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS seat_availability (id TEXT PRIMARY KEY, show_id TEXT NOT NULL REFERENCES shows(id), category TEXT NOT NULL, total INTEGER NOT NULL, available INTEGER, occupied INTEGER, source TEXT NOT NULL, data_quality TEXT NOT NULL, fetched_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS booking_links (id TEXT PRIMARY KEY, show_id TEXT NOT NULL REFERENCES shows(id), provider TEXT NOT NULL, url TEXT NOT NULL, is_affiliate INTEGER NOT NULL DEFAULT 0, deep_link_supported INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS ingestion_runs (id TEXT PRIMARY KEY, provider_key TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, records_in INTEGER NOT NULL DEFAULT 0, records_out INTEGER NOT NULL DEFAULT 0, records_rejected INTEGER NOT NULL DEFAULT 0, errors_json TEXT NOT NULL DEFAULT '[]');
CREATE INDEX IF NOT EXISTS idx_shows_movie_theatre_time ON shows(movie_id, theatre_id, starts_at);
CREATE INDEX IF NOT EXISTS idx_shows_theatre_time ON shows(theatre_id, starts_at);
CREATE INDEX IF NOT EXISTS idx_prices_show ON show_prices(show_id);
